mapper.select:
select
    date(order_time) as localDate,
    coalesce(sum(amount), 0) as turnover
from orders
where status = #{status}
  and order_time >= #{startTime}
  and order_time <= #{endTime}
group by date(order_time)
order by localDate

select
    order_detail.name,
    sum(order_detail.number) as number
from order_detail
left join orders  on orders.id = order_detail.order_id
where orders.status = #{status}
  and orders.order_time >= #{startTime}
  and orders.order_time <= #{endTime}
group by order_detail.name
order by number desc
limit #{N}
